const https = require("https");
const fs = require("fs");
const { spawnSync } = require("child_process");
const mc = "{{MC_VERSION}}";
const forge = "{{FORGE_VERSION}}";

function get(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { "user-agent": "terrypanel" } }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        res.resume();
        return get(res.headers.location).then(resolve, reject);
      }
      const chunks = [];
      res.on("data", (c) => chunks.push(c));
      res.on("end", () => resolve({ status: res.statusCode, body: Buffer.concat(chunks) }));
    }).on("error", reject);
  });
}

(async () => {
  const url = `https://maven.minecraftforge.net/net/minecraftforge/forge/${mc}-${forge}/forge-${mc}-${forge}-installer.jar`;
  console.log(`Downloading Forge ${mc}-${forge}`);
  const jar = await get(url);
  if (jar.status !== 200) throw new Error(`Forge installer download returned ${jar.status}. Check the Minecraft/Forge version pair.`);
  fs.writeFileSync("forge-installer.jar", jar.body);
  console.log("Running Forge installer");
  const result = spawnSync("java", ["-jar", "forge-installer.jar", "--installServer"], { stdio: "inherit" });
  if (result.status !== 0) throw new Error(`Forge installer exited with code ${result.status}`);
  console.log("Forge server installed. Start with the Start button.");
})().catch((err) => {
  console.error(err.message);
  process.exit(1);
});
